draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2 + Math.sin(t) * 50);
  ctx.lineTo(W, H/2 + Math.sin(t + Math.PI) * 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100 + Math.sin(t) * 20, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(50 + Math.cos(t) * 20, H/2 - 50, 100, 100);
  ctx.stroke();
  ctx.restore();
}
